        kind: 'complete',
        structured: jsonOf({ n: 1 }),
        output: { kind: 'violates', reason: 'output-check-failed' },
      },
    })
    expect(await c.invoker.cancel(alice, c1)).toBe('no-call-in-flight')
    expect(await c.invoker.invoke(alice, request(digest))).toMatchObject({
      kind: 'sent',
      outcome: { kind: 'task', taskId: 't1' },
    })
    expect(
      await c.invoker.queryTask(alice, {
        ref: files,
        taskId: taskIdOf('t1'),
        issuedAt: generationOf(1),
      }),
    ).toEqual({ ok: { status: 'working' } })
    expect(await state(c)).toEqual({ kind: 'ready' })
  })

  it('step 13: a call that breaches its contract (T9) is sent with an unknown effect: unknown (abandoned), no cancel, the key has ended and is free again', async () => {
    const base = peer({ listing: { '': TOOLS }, calls: { read: { kind: 'silent' } } })
    adoptStdio(base, files)
    let breached = 0
    const transports = reshapedTransports(base.ports.transports, transport => ({
      call: (request, signal, observe) => {
        breached += 1
        return breached === 1
          ? Promise.reject(new Error('transport bug'))
          : transport.call(request, signal, observe)
      },
    }))
    const { services: s, table } = services({ ...base, ports: { ...base.ports, transports } })
    const c = { p: base, table, ...s }
    const digest = await published(c)
    expect(await c.invoker.invoke(alice, request(digest))).toEqual({
      kind: 'sent',
      outcome: { kind: 'unknown', cause: 'abandoned' },
    })
    expect(base.cancels()).toBe(0)
    expect(await c.invoker.cancel(alice, c1)).toBe('no-call-in-flight')
    expect(await state(c)).toEqual({ kind: 'ready' })
    const next = c.invoker.invoke(alice, request(digest))
    await settled()
    expect(breached).toBe(2)
    expect(await c.invoker.cancel(alice, c1)).toBe('signalled')
    expect(await next).toEqual({ kind: 'sent', outcome: { kind: 'unknown', cause: 'abandoned' } })
  })

  it('step 10: a call sent on one generation, whose connection is lost and rebuilt before call returns: a later cancel answers unknown and tells no peer (MC-12)', async () => {
    const gate = deferred<void>()
    let calls = 0
    const base = peer({ listing: { '': TOOLS }, calls: { read: { kind: 'silent' } } })
    const transports = reshapedTransports(base.ports.transports, transport => ({
      async call(request, signal, observe) {
        const called = await transport.call(request, signal, observe)
        calls += 1
        if (calls !== 1 || 'failure' in called) return called
        // The send is recorded only once the case lets `call` return; the answer never comes.
        await gate.promise
        return { ok: { requestId: called.ok.requestId, answer: never() } }
      },
    }))
    adoptStdio(base, files)
    const { services: s, table } = services({ ...base, ports: { ...base.ports, transports } })
    const c = { p: base, table, ...s }
    const digest = await published(c)
    const [first] = table.currentOf(alice.tenant, files.holding)
    if (first === undefined) throw new Error('no connection')
    expect(first.generation).toBe(1)
    const controller = new AbortController()
    const call = c.invoker.invoke(alice, request(digest, { signal: controller.signal }))
    await settled()
    expect(base.requests('tools/call')).toHaveLength(1)
    expect(
      await loseOn(table, first, { reason: 'stream-broken', mark: 'connection-unavailable' }),
    ).not.toBe('not-current')
    expect(await c.discovery.refresh(alice, { ref: files })).toMatchObject({ ok: {} })
    const [second] = table.currentOf(alice.tenant, files.holding)
    expect(second?.generation).toBe(2)
    gate.resolve()
    await settled()
    await settled()
    expect(await c.invoker.cancel(alice, c1)).toBe('unknown')
    expect(base.cancels()).toBe(0)
    controller.abort()
    expect(await call).toEqual({ kind: 'sent', outcome: { kind: 'unknown', cause: 'abandoned' } })
  })
})

tests/shutdown.spec.ts.source:
// The shutdown (SPEC decisions 5 and 6): `closeAll` releases the handles of the landings in flight
// at once, whatever another entry's close waits on, and a build that is under way when the table
// shuts goes no further than the step it is in. Steps are ordered with deferred promises; the only
// timers are the connection bounds under test.
import { describe, expect, it } from 'vitest'
import { only } from './doubles/calls.ts'
import { manualBounds } from './doubles/bounds.ts'
import { core } from './doubles/core.ts'
import { deferred, settled } from './doubles/deferred.ts'
import { stallingCredentials, stallingLanding, stallingStops } from './doubles/stalls.ts'
import type { PeerIdentity } from '@omne-harness/mcp-contract'
import { millisOf, peerIdentityOf, endpointRefOf } from '@omne-harness/mcp-contract/testing'
import { alice } from './doubles/identities.ts'
import { VALUE, adoptStdio, usualScript, world, type World } from './doubles/world.ts'

const files = endpointRefOf('files')
const notes = endpointRefOf('notes')
const WITH_CREDENTIAL = {
  auth: 'static',
  env: [{ name: 'TOKEN', source: 'credential' }],
} as const
const REFUSED = { failure: { kind: 'connection-unavailable' } }
const ANONYMOUS_KEY = {
  tenant: alice.tenant,
  account: { kind: 'anonymous' as const },
  holding: files.holding,
}

function opens(w: World): number {
  return w.transports.calls.filter(call => call.kind === 'open').length
}

describe('closeAll releases the handles of the landings in flight at once (decision 6)', () => {
  it('while the close of another entry waits on its transport', async () => {
    const closing = deferred<'closed'>()
    const w = world({ script: [...usualScript(), { close: closing }] })
    adoptStdio(w, files)
    adoptStdio(w, notes, {
      ...WITH_CREDENTIAL,
      settings: { connectTimeout: VALUE(millisOf(50)) },
    })
    // The start for `files` is call 1 and lands; the start for `notes` is call 2 and never does.
    const stalled = stallingLanding(w.landing, only(2))
    const c = core({ ...w, ports: { ...w.ports, landing: stalled.port } })
    expect(await c.discovery.refresh(alice, { ref: files })).toMatchObject({
      ok: { kind: 'published' },
    })
    expect(await c.discovery.refresh(alice, { ref: notes })).toEqual(REFUSED)
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 0 }])
    const all = c.connections.closeAll()
    await settled()
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 1 }])
    closing.resolve('closed')
    expect(await all).toEqual([
      { ref: files, process: 'tree-confirmed' },
      { ref: notes, process: 'unconfirmed' },
    ])
  })

  it('for a landing that outlives its bound after the shutdown began; the late process is stopped once', async () => {
    const w = world({ script: usualScript() })
    adoptStdio(w, files, {
      ...WITH_CREDENTIAL,
      settings: { connectTimeout: VALUE(millisOf(50)) },
    })
    const stalled = stallingLanding(w.landing)
    const c = core({ ...w, ports: { ...w.ports, landing: stalled.port } })
    const refreshed = c.discovery.refresh(alice, { ref: files })
    await settled()
    expect(stalled.calls()).toBe(1)
    const all = c.connections.closeAll()
    expect(await refreshed).toEqual(REFUSED)
    expect(await all).toEqual([{ ref: files, process: 'unconfirmed' }])
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 1 }])
    stalled.gate.resolve()
    await settled()
    expect(w.landing.processes()).toEqual([{ stops: 1 }])
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 1 }])
  })

  it('for a landing still within its bound: released before the landing answers; the process that lands is stopped and its handle not released again', async () => {
    const w = world({ script: usualScript() })
    adoptStdio(w, files, WITH_CREDENTIAL)
    const bounds = manualBounds()
    const stalled = stallingLanding(w.landing)
    const c = core({ ...w, ports: { ...w.ports, landing: stalled.port } }, bounds.runtime)
    const refreshed = c.discovery.refresh(alice, { ref: files })
    await settled()
    expect(stalled.calls()).toBe(1)
    const all = c.connections.closeAll()
    await settled()
    // No bound fired: the landing is in flight within its bound, and its handle is released.
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 1 }])
    stalled.gate.resolve()
    expect(await refreshed).toEqual(REFUSED)
    expect(await all).toEqual([{ ref: files, process: 'no-process' }])
    expect(w.landing.processes()).toEqual([{ stops: 1 }])
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 1 }])
  })

  it('not for a landing that already handed over its process: the handle waits for its stop (S9)', async () => {
    const w = world({ script: usualScript() })
    adoptStdio(w, files, {
      ...WITH_CREDENTIAL,
      settings: { connectTimeout: VALUE(millisOf(50)) },
    })
    const stops = stallingStops(w.landing, only(1))
    const landing = stallingLanding(stops.port)
    const c = core({ ...w, ports: { ...w.ports, landing: landing.port } })
    expect(await c.discovery.refresh(alice, { ref: files })).toEqual(REFUSED)
    landing.gate.resolve()
    await settled()
    // The late process is being stopped; it carries the handle in its environment.
    const all = c.connections.closeAll()
    await settled()
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 0 }])
    stops.gate.resolve()
    await all
    await settled()
    expect(w.trace).toEqual(['process.stop', 'credential.release'])
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 1 }])
  })
})

describe('a build under way when the table shuts goes no further (decision 5)', () => {
  it('shut while the credential is asked: no process starts, no transport opens, the handle is released once', async () => {
    const w = world({ script: usualScript() })
    adoptStdio(w, files, WITH_CREDENTIAL)
    const credentials = stallingCredentials(w.ports.credentials)
    const c = core({ ...w, ports: { ...w.ports, credentials: credentials.port } })
    const refreshed = c.discovery.refresh(alice, { ref: files })
    await settled()
    const all = c.connections.closeAll()
    await settled()
    credentials.gate.resolve()
    expect(await refreshed).toEqual(REFUSED)
    expect(await all).toEqual([{ ref: files, process: 'no-process' }])
    expect(w.landing.processes()).toEqual([])
    expect(opens(w)).toBe(0)
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 1 }])
  })

  it('shut while the process starts: the process that lands is stopped and no transport opens', async () => {
    const w = world({ script: usualScript() })
    adoptStdio(w, files, WITH_CREDENTIAL)
    const stalled = stallingLanding(w.landing)
    const c = core({ ...w, ports: { ...w.ports, landing: stalled.port } })
    const refreshed = c.discovery.refresh(alice, { ref: files })
    await settled()
    expect(stalled.calls()).toBe(1)
    const all = c.connections.closeAll()
    await settled()
    stalled.gate.resolve()
    expect(await refreshed).toEqual(REFUSED)
    expect(await all).toEqual([{ ref: files, process: 'no-process' }])
    expect(w.landing.processes()).toEqual([{ stops: 1 }])
    expect(opens(w)).toBe(0)
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 1 }])
  })

  it('shut while negotiating: the same refusal as after the shutdown, not a connection about to be torn down (decision 23)', async () => {
    const discover = deferred<PeerIdentity>()
    const w = world({ script: [{ discover }] })
    adoptStdio(w, files, WITH_CREDENTIAL)
    const c = core(w)
    const refreshed = c.discovery.refresh(alice, { ref: files })
    await settled()
    const all = c.connections.closeAll()
    await settled()
    discover.resolve(peerIdentityOf())
    expect(await refreshed).toEqual(REFUSED)
    await all
    expect(w.trace).toEqual(['transport.close', 'process.stop', 'credential.release'])
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 1 }])
  })
})

describe('a build cut off by the shutdown marks nothing', () => {
  it('the catalog keeps its revision: the shutdown is a fact of this instance, not of the endpoint', async () => {
    const w = world({ script: [...usualScript(), ...usualScript()] })
    adoptStdio(w, files)
    // The first start lands at once; the start of the rebuild waits until the table is shut.
    const stalled = stallingLanding(w.landing, only(2))
    const c = core({ ...w, ports: { ...w.ports, landing: stalled.port } })
    expect(await c.discovery.refresh(alice, { ref: files })).toMatchObject({
      ok: { kind: 'published' },
    })
    const published = await w.store.read(ANONYMOUS_KEY)
    expect(await c.connections.release(alice, files)).toEqual({
      ok: { kind: 'released', process: 'tree-confirmed' },
    })
    const refreshed = c.discovery.refresh(alice, { ref: files })
    await settled()
    expect(stalled.calls()).toBe(2)
    const all = c.connections.closeAll()
    await settled()
    stalled.gate.resolve()
    expect(await refreshed).toEqual(REFUSED)
    expect(await all).toEqual([{ ref: files, process: 'no-process' }])
    expect(await w.store.read(ANONYMOUS_KEY)).toEqual(published)
  })

  it('a build that fails after the shutdown began marks nothing either, and answers as after the shutdown (takeover ruling K3)', async () => {
    const w = world({ script: [...usualScript(), ...usualScript()] })
    adoptStdio(w, files)
    const bounds = manualBounds()
    const stalled = stallingLanding(w.landing, only(2))
    const c = core({ ...w, ports: { ...w.ports, landing: stalled.port } }, bounds.runtime)
    expect(await c.discovery.refresh(alice, { ref: files })).toMatchObject({
      ok: { kind: 'published' },
    })
    const published = await w.store.read(ANONYMOUS_KEY)
    expect(await c.connections.release(alice, files)).toEqual({
      ok: { kind: 'released', process: 'tree-confirmed' },
    })
    const refreshed = c.discovery.refresh(alice, { ref: files })
    await settled()
    expect(stalled.calls()).toBe(2)
    const all = c.connections.closeAll()
    await settled()
    // The rebuild's bound fires after the shutdown began: the build fails at the landing.
    bounds.fire('build', 1)
    expect(await refreshed).toEqual(REFUSED)
    expect(await all).toEqual([{ ref: files, process: 'unconfirmed' }])
    expect(await w.store.read(ANONYMOUS_KEY)).toEqual(published)
  })
})

describe('closeAll hands the errors of the background work to its caller (SPEC P7)', () => {
  it('rejects once with an AggregateError that holds them; an error after it goes to the outlet of the scope', async () => {
    const w = world()
    const late: unknown[] = []
    const bounds = manualBounds(error => late.push(error))
    const c = core(w, bounds.runtime)
    const bug = new Error('an error of this package in the background')
    c.table.runtime.scope.spawn(Promise.reject(bug))
    await settled()
    const thrown = await c.connections.closeAll().then(
      () => undefined,
      (error: unknown) => error,
    )
    expect(thrown).toBeInstanceOf(AggregateError)
    expect(thrown instanceof AggregateError ? thrown.errors : []).toEqual([bug])
    expect(await c.connections.closeAll()).toEqual([])
    const after = new Error('after the exit')
    c.table.runtime.scope.spawn(Promise.reject(after))
    await settled()
    expect(late).toEqual([after])
  })
})

tests/cancel.spec.ts.source:
// The call port `cancel` (SPEC S2, MC-12, MC-16): it reads the in-flight table only, so another
// principal or tenant on the same correlation key gets `unknown`; from the reservation on, a
// cancel and the caller's abort fire the one stop signal of the call, so a stop before the send
// keeps the call off the wire and ends the key, and a stop after the send, or between the send
// and its record, tells the peer once, does not wait for it, and ends the call as unknown
// (abandoned).
import { describe, expect, it } from 'vitest'
import {
  digestDefinition,
  type DefinitionDigest,
  type InvokeRequest,
  type InvokeResult,
} from '@omne-harness/mcp-contract'
import {
  actionNameOf,
  correlationKeyOf,
  endpointRefOf,
  jsonOf,
  type Replies,
} from '@omne-harness/mcp-contract/testing'
import { deferred, settled } from './doubles/deferred.ts'
import { alice, aliceAway, bob, mallory } from './doubles/identities.ts'
import { completed, listing, peer, services, text, type Peer } from './doubles/peer.ts'
import { stallingEligibility, stallingLanding } from './doubles/stalls.ts'
import { never, reshapedTransports } from './doubles/transports.ts'
import { adoptStdio, storedRecord } from './doubles/world.ts'

const files = endpointRefOf('files')
const READ = actionNameOf('read')
const c1 = correlationKeyOf('c1')
const anonymousKey = {
  tenant: alice.tenant,
  account: { kind: 'anonymous' as const },
  holding: files.holding,
}

/** A peer that lists `read` and answers it as scripted, adopted for alice, with the catalog stored. */
async function arranged(read: Replies, options: Parameters<typeof peer>[1] = {}) {
  const p = peer({ listing: { '': listing([{ name: 'read' }]) }, calls: { read } }, options)
  adoptStdio(p, files)
  const stored = await storedRecord(p, anonymousKey, ['read'])
  const digest = stored.actions[0]?.definitionDigest
  if (digest === undefined) throw new Error('no digest')
  return { p, digest }
}

function request(expectedDefinition: DefinitionDigest, signal?: AbortSignal): InvokeRequest {
  return {
    ref: files,
    action: READ,
    args: jsonOf({}),
    expectedDefinition,
    correlationKey: c1,
    signal: signal ?? new AbortController().signal,
  }
}

const ABANDONED = { kind: 'sent', outcome: { kind: 'unknown', cause: 'abandoned' } }

function portCalls(p: Peer) {
  return { adoption: p.adoption.calls(), eligibility: p.eligibility.calls() }
}

/**
 * A call gate that tells the case when the call reached the transport (`before` the send, or
 * `after` it), and holds the call there until the case releases it: the case orders a cancel
 * against the send by what has happened, not by a number of turns.
 */
function holdingAt(where: 'before' | 'after') {
  const reached = deferred<void>()
  const held = deferred<void>()
  const hold = async () => {
    reached.resolve()
    await held.promise
  }
  return {
    reached: reached.promise,
    release: () => held.resolve(),
    callGate: where === 'before' ? { before: hold } : { after: hold },
  }
}

describe('cancel reads the in-flight table only (SPEC S2)', () => {
  it('answers unknown to another principal and to another tenant on the same correlation key, and asks no port', async () => {
    const hold = holdingAt('after')
    const { p, digest } = await arranged({ kind: 'silent' }, { callGate: hold.callGate })
    const { services: s } = services(p)
    const call = s.invoker.invoke(alice, request(digest))
    await hold.reached
    const asked = portCalls(p)
    expect(await s.invoker.cancel(bob, c1)).toBe('unknown')
    expect(await s.invoker.cancel(mallory, c1)).toBe('unknown')
    expect(await s.invoker.cancel(aliceAway, c1)).toBe('unknown')
    expect(portCalls(p)).toEqual(asked)
    expect(p.cancels()).toBe(0)
    expect(await s.invoker.cancel(alice, c1)).toBe('signalled')
    hold.release()
    expect(await call).toEqual(ABANDONED)
    await settled()
    expect(p.cancels()).toBe(1)
  })

  it('answers unknown for a key never used, and no-call-in-flight for a call that ended', async () => {
    const { p, digest } = await arranged(completed([text('hi')]))
    const { services: s } = services(p)
    expect(await s.invoker.cancel(alice, c1)).toBe('unknown')
    expect(await s.invoker.invoke(alice, request(digest))).toMatchObject({ kind: 'sent' })
    expect(await s.invoker.cancel(alice, c1)).toBe('no-call-in-flight')
  })
})

describe('a cancel before the send (SPEC S2, MC-16 steps 2–8)', () => {
  it('makes the call answer not sent (cancelled) with no call on the wire; the key has ended', async () => {
    const { p, digest } = await arranged(completed([text('hi')]))
    // The invoke's gate is the first eligibility call; it waits until the case lets it go.
    const stalled = stallingEligibility(p.eligibility, 1)
    const { services: s } = services({ ...p, ports: { ...p.ports, eligibility: stalled.port } })
    const call = s.invoker.invoke(alice, request(digest))
    await settled()
    expect(stalled.calls()).toBe(1)
    expect(await s.invoker.cancel(alice, c1)).toBe('signalled')
    stalled.gate.resolve()
    expect(await call).toEqual({ kind: 'not-sent', reason: { kind: 'cancelled' } })
    expect(p.requests('tools/call')).toHaveLength(0)
    expect(p.opens()).toBe(0)
    expect(p.cancels()).toBe(0)
    expect(await s.invoker.cancel(alice, c1)).toBe('no-call-in-flight')
  })

  it('step 8: at whichever microtask the cancel lands, the transport is never called with a stop signal that fired', async () => {
    // The cancel lands k microtasks after the invoke, for every k up to the one at which the call
    // has concluded already (the cancel answers no-call-in-flight). The last wait of the send
    // order and `transport.call` are a few microtasks apart; a stop that lands in between must
    // keep the call off the transport, not be left to the transport's own T5 answer.
    const LIMIT = 400
    let concluded = false
    for (let k = 0; k < LIMIT && !concluded; k += 1) {
      const { p, digest } = await arranged(completed([text('hi')]))
      const stopsSeen: boolean[] = []
      const transports = reshapedTransports(p.ports.transports, transport => ({
        call(request, signal, observe) {
          stopsSeen.push(signal.aborted)
          return transport.call(request, signal, observe)
        },
      }))
      const { services: s } = services({ ...p, ports: { ...p.ports, transports } })
      const call = s.invoker.invoke(alice, request(digest))
      for (let i = 0; i < k; i += 1) await Promise.resolve()
      const answer = await s.invoker.cancel(alice, c1)
      const result = await call
      expect(stopsSeen, `k=${k}: transport.call entered with the stop fired`).not.toContain(true)
      if (result.kind === 'not-sent') {
        expect(result.reason, `k=${k}`).toEqual({ kind: 'cancelled' })
        expect(p.requests('tools/call'), `k=${k}`).toHaveLength(0)
      }
      concluded = answer === 'no-call-in-flight'
    }
    expect(concluded).toBe(true)
  })
})

describe('a cancel after the send (SPEC S2, MC-16 step 11)', () => {
  it('tells the peer once and ends the call as unknown (abandoned), without waiting for the peer', async () => {
    const { p, digest } = await arranged({ kind: 'silent' })
    const { services: s } = services(p)
    const call = s.invoker.invoke(alice, request(digest))
    await settled()
    expect(p.requests('tools/call')).toHaveLength(1)
    expect(await s.invoker.cancel(alice, c1)).toBe('signalled')
    expect(await call).toEqual(ABANDONED)
    expect(p.cancels()).toBe(1)
    expect(await s.invoker.cancel(alice, c1)).toBe('no-call-in-flight')
    expect(p.cancels()).toBe(1)
  })

  it('that lands between the send and its record is the same: the call is on the wire, so the peer is told once', async () => {
    const hold = holdingAt('after')
    const { p, digest } = await arranged(completed([text('hi')]), { callGate: hold.callGate })
    const { services: s } = services(p)
    const call = s.invoker.invoke(alice, request(digest))
    await hold.reached
    expect(p.requests('tools/call')).toHaveLength(1)
    expect(await s.invoker.cancel(alice, c1)).toBe('signalled')
    hold.release()
    expect(await call).toEqual(ABANDONED)
    await settled()
    expect(p.cancels()).toBe(1)
  })

  it('that races the send, which the transport then refuses, is a cancel before the send: nothing is lost', async () => {
    const hold = holdingAt('before')
    const { p, digest } = await arranged(completed([text('hi')]), { callGate: hold.callGate })
    const { services: s } = services(p)
    const call = s.invoker.invoke(alice, request(digest))
    await hold.reached
    expect(await s.invoker.cancel(alice, c1)).toBe('signalled')
    hold.release()
    expect(await call).toEqual({ kind: 'not-sent', reason: { kind: 'cancelled' } })
    expect(p.requests('tools/call')).toHaveLength(0)
    expect(p.cancels()).toBe(0)
    expect(await s.status.inspect(alice, files)).toMatchObject({
      ok: { connection: { kind: 'ready' } },
    })
  })

  it('that races the send, followed by closeAll, which the transport then refuses: cancelled, not connection-unavailable; the stop signal is read before the shutdown (S2, S8)', async () => {
    const hold = holdingAt('before')
    const { p, digest } = await arranged(completed([text('hi')]), { callGate: hold.callGate })
    const { services: s } = services(p)
    const call = s.invoker.invoke(alice, request(digest))
    await hold.reached
    expect(await s.invoker.cancel(alice, c1)).toBe('signalled')
    const closing = s.connections.closeAll()
    hold.release()
    expect(await call).toEqual({ kind: 'not-sent', reason: { kind: 'cancelled' } })
    await closing
    expect(p.requests('tools/call')).toHaveLength(0)
    expect(p.cancels()).toBe(0)
  })

  it('that races the send, which the transport then refuses for an ended session, is cancelled too, but the connection is lost: the answer carries the mark that the transport is not usable any more (T1, S7)', async () => {
    const hold = holdingAt('before')
    const base = await arranged(completed([text('hi')]), { callGate: hold.callGate })
    // The scripted transport answers a fired signal with an unmarked connection-unavailable (T5);
    // this one reports an ended legacy session instead, marked as the decision layer marks it.
    const transports = reshapedTransports(base.p.ports.transports, transport => ({
      async call(request, signal, observe) {
        await transport.call(request, signal, observe)
        return { failure: { kind: 'not-sent', cause: 'session-ended', unusable: 'session-ended' } }
      },
    }))
    const { services: s } = services({ ...base.p, ports: { ...base.p.ports, transports } })
    const call = s.invoker.invoke(alice, request(base.digest))
    await hold.reached
    expect(await s.invoker.cancel(alice, c1)).toBe('signalled')
    hold.release()
    expect(await call).toEqual({ kind: 'not-sent', reason: { kind: 'cancelled' } })
    expect(base.p.cancels()).toBe(0)
    expect(await s.status.inspect(alice, files)).toMatchObject({
      ok: { connection: { kind: 'lost', reason: 'session-ended' } },
    })
  })

  it('with the caller abort too tells the peer once only', async () => {
    const hold = holdingAt('after')
    const { p, digest } = await arranged({ kind: 'silent' }, { callGate: hold.callGate })
    const { services: s } = services(p)
    const controller = new AbortController()
    const call = s.invoker.invoke(alice, request(digest, controller.signal))
    await hold.reached
    expect(await s.invoker.cancel(alice, c1)).toBe('signalled')
    controller.abort()
    hold.release()
    expect(await call).toEqual(ABANDONED)
    await settled()
    expect(p.cancels()).toBe(1)
  })
})

const CANCELLED = { kind: 'not-sent', reason: { kind: 'cancelled' } }

/** `n` turns of the event loop: a bound on how long an answer may take once nothing is awaited. */
async function turns(n: number): Promise<void> {
  for (let i = 0; i < n; i += 1) await settled()
}

/** The result of `call` once it settled, else `pending`: the test reads it after some turns. */
function tracked(call: Promise<InvokeResult>) {
  let answer: InvokeResult | 'pending' = 'pending'
  const done = call.then(result => {
    answer = result
  })
  return { read: () => answer, done }
}

describe('one stop signal from the reservation on (SPEC S2, MC-16 step 2)', () => {
  it.each(['cancel', 'abort'] as const)(
    'after the send, a %s does not wait for cancelRequest: the call answers unknown (abandoned) within a few turns',
    async how => {
      const { p, digest } = await arranged({ kind: 'silent' })
      let hanging = 0
      const transports = reshapedTransports(p.ports.transports, () => ({
        cancelRequest: () => {
          hanging += 1
          return never()
        },
      }))
      const { services: s } = services({ ...p, ports: { ...p.ports, transports } })
      const controller = new AbortController()
      const call = tracked(s.invoker.invoke(alice, request(digest, controller.signal)))
      await settled()
      expect(p.requests('tools/call')).toHaveLength(1)
      if (how === 'cancel') expect(await s.invoker.cancel(alice, c1)).toBe('signalled')
      else controller.abort()
      await turns(5)
      expect(call.read()).toEqual(ABANDONED)
      expect(hanging).toBe(1)
      expect(await s.invoker.cancel(alice, c1)).toBe('no-call-in-flight')
      await call.done
    },
  )

  it('a cancel while the gate is asked, followed by a refusing step, answers cancelled, and the key has ended', async () => {
    const { p } = await arranged(completed([text('hi')]))
    const stalled = stallingEligibility(p.eligibility, 1)
    const { services: s } = services({ ...p, ports: { ...p.ports, eligibility: stalled.port } })
    // The expected definition is stale: step 5 would refuse with definition-changed.
    const stale = digestDefinition({ name: READ, definition: jsonOf({ name: 'read', v: 2 }) })
    const call = s.invoker.invoke(alice, request(stale))
    await settled()
    expect(stalled.calls()).toBe(1)
    expect(await s.invoker.cancel(alice, c1)).toBe('signalled')
    stalled.gate.resolve()
    expect(await call).toEqual(CANCELLED)
    expect(p.requests('tools/call')).toHaveLength(0)
    expect(await s.invoker.cancel(alice, c1)).toBe('no-call-in-flight')
  })

  it('a cancel the call answers signalled, at whichever microtask it lands, makes the call answer cancelled, not the setting defect that refuses it in the same turn', async () => {
    // No connect-timeout and no connectBound: step 4 refuses with config-missing in the same
    // synchronous run as the gate's answer. The cancel lands k microtasks after the invoke; one
    // k falls between the gate's answer and the resumption of the wait, where only the look at
    // the stop signal after the wait tells the two apart.
    const LIMIT = 400
    let concluded = false
    for (let k = 0; k < LIMIT && !concluded; k += 1) {
      const p = peer({
        listing: { '': listing([{ name: 'read' }]) },
        calls: { read: completed([]) },
      })
      adoptStdio(p, files, { settings: { connectTimeout: { kind: 'absent' } } })
      await storedRecord(p, anonymousKey, ['read'])
      const { services: s } = services(p)
      const digest = digestDefinition({ name: READ, definition: jsonOf({ name: 'read' }) })
      const call = s.invoker.invoke(alice, request(digest))
      for (let i = 0; i < k; i += 1) await Promise.resolve()
      const answer = await s.invoker.cancel(alice, c1)
      const result = await call
      if (answer === 'signalled') expect(result, `k=${k}`).toEqual(CANCELLED)
      else
        expect(result, `k=${k}`).toEqual({
          kind: 'not-sent',
          reason: { kind: 'config-missing', item: 'connect-timeout' },
        })
      concluded = answer !== 'signalled'
    }
    expect(concluded).toBe(true)
  })

  it.each(['cancel', 'abort'] as const)(
    'a store read that never answers: a %s ends the wait, the call answers cancelled, and the key has ended',
    async how => {
      const { p, digest } = await arranged(completed([text('hi')]))
      const store = { ...p.store, read: () => never<never>() }
      const { services: s } = services({ ...p, ports: { ...p.ports, store } })
      const controller = new AbortController()
      const call = tracked(s.invoker.invoke(alice, request(digest, controller.signal)))
      await turns(2)
      expect(call.read()).toBe('pending')
      if (how === 'cancel') expect(await s.invoker.cancel(alice, c1)).toBe('signalled')
      else controller.abort()
      await turns(5)
      expect(call.read()).toEqual(CANCELLED)
      expect(p.requests('tools/call')).toHaveLength(0)
      expect(await s.invoker.cancel(alice, c1)).toBe('no-call-in-flight')
      await call.done
    },
  )

  it.each(['cancel', 'abort'] as const)(
    'while the build is under way, a %s answers the call cancelled at once; the build goes on for the key and nothing is sent',
    async how => {
      const { p, digest } = await arranged(completed([text('hi')]))
      const stalled = stallingLanding(p.landing)
      const { services: s } = services({ ...p, ports: { ...p.ports, landing: stalled.port } })
      const controller = new AbortController()
      const call = tracked(s.invoker.invoke(alice, request(digest, controller.signal)))
      await settled()
      expect(stalled.calls()).toBe(1)
      if (how === 'cancel') expect(await s.invoker.cancel(alice, c1)).toBe('signalled')
      else controller.abort()
      await turns(5)
      expect(call.read()).toEqual(CANCELLED)
      expect(await s.invoker.cancel(alice, c1)).toBe('no-call-in-flight')
      stalled.gate.resolve()
      await turns(5)
      expect(p.requests('tools/call')).toHaveLength(0)
      expect(p.opens()).toBe(1)
      expect(await s.status.inspect(alice, files)).toMatchObject({
        ok: { connection: { kind: 'ready' } },
      })
      await call.done
    },
  )

  it('a signal that fired before the call starts no wait: no port is asked, the call answers cancelled', async () => {
    const { p, digest } = await arranged(completed([text('hi')]))
    const { services: s } = services(p)
    const asked = portCalls(p)
    const controller = new AbortController()
    controller.abort()
    expect(await s.invoker.invoke(alice, request(digest, controller.signal))).toEqual(CANCELLED)
    expect(portCalls(p)).toEqual(asked)
    expect(p.opens()).toBe(0)
    expect(await s.invoker.cancel(alice, c1)).toBe('no-call-in-flight')
  })
})

