describe('ensure: the connection key (invariant 1)', () => {
  it('does not share a connection between two tenants with the same holding and adoption revision', async () => {
    const w = world({ script: [{ discover: peer }, { discover: peer }] })
    const { revision } = adoptStdio(w, files)
    w.adoption.adopt({
      tenant: away,
      scope: 'ws',
      ref: files,
      body: jsonOf({ name: 'files', transport: 'stdio', auth: 'none', launch: { command: 'x' } }),
      settings: {
        target: { kind: 'absent' },
        credential: { kind: 'absent' },
        connectTimeout: VALUE(millisOf(1000)),
      },
    })
    w.eligibility.grant(mallory, files)
    // The double gives every adoption its own revision. Here both tenants read one revision, so
    // the tenant is the only part of the two connection keys that differs.
    const adoption: AdoptionView<Principal, string> = {
      endpoints: (access, scope) => w.ports.adoption.endpoints(access, scope),
      endpoint: async (access, endpoint) => {
        const read = await w.ports.adoption.endpoint(access, endpoint)
        return 'ok' in read && read.ok !== 'not-adopted' ? { ok: { ...read.ok, revision } } : read
      },
    }
    const ports = { ...w.ports, adoption }
    const table = createConnectionTable(ports, w.config)
    const ourToken = await admit(ports, alice, files)
    const theirToken = await admit(ports, mallory, files)
    if (ourToken.kind !== 'admitted' || theirToken.kind !== 'admitted')
      throw new Error('not admitted')
    const ours = await table.ensure(ourToken.endpoint, alice)
    const theirs = await table.ensure(theirToken.endpoint, mallory)
    if (!('ok' in ours) || !('ok' in theirs)) throw new Error('ensure failed')
    expect(theirs.ok.adoptionRevision).toBe(ours.ok.adoptionRevision)
    expect(theirs.ok.transport).not.toBe(ours.ok.transport)
    expect(w.transports.calls.filter(call => call.kind === 'open')).toHaveLength(2)
  })

  it('does not share a connection between two peer accounts of the same adoption revision', async () => {
    // An adoption view that keeps one revision text while the credential binding changes. The
    // contract forbids this (AV5); the key must still keep the accounts apart.
    const w = world({ script: [{ discover: peer }, { discover: peer }] })
    const base = adoptHttp(w, files)
    w.credentials.store({
      tenant: alice.tenant,
      holding: files.holding,
      binding: credentialBindingOf('other'),
      secret: 's2',
    })
    let current: AdoptedEndpoint = base
    const adoption: AdoptionView<Principal, string> = {
      endpoints: async () => ({ ok: [current] }),
      endpoint: async () => ({ ok: current }),
    }
    const ports = { ...w.ports, adoption }
    const table = createConnectionTable(ports, w.config)
    const first = await admit(ports, alice, files)
    if (first.kind !== 'admitted') throw new Error('not admitted')
    const ours = await table.ensure(first.endpoint, alice)
    current = {
      ...base,
      settings: { ...base.settings, credential: VALUE(credentialBindingOf('other')) },
    }
    const second = await admit(ports, alice, files)
    if (second.kind !== 'admitted') throw new Error('not admitted')
    const theirs = await table.ensure(second.endpoint, alice)
    if (!('ok' in ours) || !('ok' in theirs)) throw new Error('ensure failed')
    expect(theirs.ok.transport).not.toBe(ours.ok.transport)
    expect(theirs.ok.catalogKey.account).toEqual({ kind: 'credential', binding: 'other' })
    expect(ours.ok.catalogKey.account).toEqual({ kind: 'credential', binding: 'main' })
    expect(w.transports.calls.filter(call => call.kind === 'open')).toHaveLength(2)
  })

  it('closes the connection of an earlier adoption revision before using the new one', async () => {
    const w = world({ script: [{ discover: peer }, { discover: peer }] })
    adoptStdio(w, files)
    const table = tableOf(w)
    const first = await table.ensure(await admitted(w, files), alice)
    if (!('ok' in first)) throw new Error('ensure failed')
    w.adoption.update(alice.tenant, files, { processEnv: [{ name: 'X', value: '1' }] })
    const second = await table.ensure(await admitted(w, files), alice)
    if (!('ok' in second)) throw new Error('ensure failed')
    expect(first.ok.connection.isCurrent(first.ok.generation)).toBe(false)
    expect(second.ok.transport).not.toBe(first.ok.transport)
    expect(w.transports.calls.map(call => call.kind)).toEqual([
      'open',
      'discover',
      'close',
      'open',
      'discover',
    ])
    expect(w.landing.processes()).toEqual([{ stops: 1 }, { stops: 0 }])
  })

  it('carries the target and the HTTP handle in the material of an HTTP connection', async () => {
    const w = world({ script: [{ discover: peer }] })
    adoptHttp(w, files)
    const table = tableOf(w)
    await table.ensure(await admitted(w, files), alice)
    const opens = w.transports.calls.flatMap(call => (call.kind === 'open' ? [call.material] : []))
    expect(opens[0]).toMatchObject({ kind: 'streamable-http', target: TARGET, generation: 1 })
    expect(opens[0]?.kind === 'streamable-http' && opens[0].credential?.purpose).toBe(
      'http-authorization',
    )
  })

  it('carries the process in the material of a stdio connection, with the credential variables', async () => {
    const w = world({ script: [{ discover: peer }] })
    adoptStdio(w, files, { auth: 'static', env: [{ name: 'TOKEN', source: 'credential' }] })
    const table = tableOf(w)
    await table.ensure(await admitted(w, files), alice)
    const opens = w.transports.calls.flatMap(call => (call.kind === 'open' ? [call.material] : []))
    expect(opens[0]).toMatchObject({ kind: 'stdio', generation: 1, instructionsByteLimit: 4096 })
    expect(w.landing.started()[0]?.env.credentials.map(item => item.name)).toEqual(['TOKEN'])
  })
})

describe('ensure: the adoption is read again before a build (MC-5)', () => {
  it('answers not-available-to-you for a token of an endpoint withdrawn after the gate, and builds nothing', async () => {
    const w = world({ script: [{ discover: peer }] })
    adoptStdio(w, files)
    const table = tableOf(w)
    const token = await admitted(w, files)
    w.adoption.withdraw(alice.tenant, files)
    expect(await table.ensure(token, alice)).toEqual({
      failure: { stage: 'settings', reason: { kind: 'not-available-to-you' } },
    })
    expect(w.transports.calls).toHaveLength(0)
    expect(w.landing.started()).toHaveLength(0)
    expect(table.stateOf(alice.tenant, files.holding)).toEqual({ kind: 'none' })
  })

  it('answers unknown when the adoption cannot be read again, and builds nothing', async () => {
    const w = world({ script: [{ discover: peer }] })
    adoptStdio(w, files)
    const table = tableOf(w)
    const token = await admitted(w, files)
    w.adoption.setUnreadable(true)
    expect(await table.ensure(token, alice)).toEqual({
      failure: { stage: 'settings', reason: { kind: 'unknown' } },
    })
    expect(w.transports.calls).toHaveLength(0)
    expect(table.stateOf(alice.tenant, files.holding)).toEqual({ kind: 'none' })
  })
})

tests/continue.spec.ts.source:
// The call port `continueWithInput` (SPEC S2, MC-16): a continuation completes on the generation
// the `inputRequired` outcome was issued at; once the connection changed generation it is not
// sent, and nothing is sent on the new generation; the request state alone is a lawful
// continuation.
import { describe, expect, it } from 'vitest'
import type { JsonValue } from '@omne-harness/json-text'
import type {
  DefinitionDigest,
  Generation,
  McpPorts,
  RequestState,
} from '@omne-harness/mcp-contract'
import {
  actionNameOf,
  correlationKeyOf,
  endpointRefOf,
  generationOf,
  jsonOf,
  requestStateOf,
  type PeerReply,
} from '@omne-harness/mcp-contract/testing'
import { loseOn } from '../src/internal/lost.ts'
import { settled } from './doubles/deferred.ts'
import { alice, type Principal } from './doubles/identities.ts'
import { completed, listing, peer, services, text, type Peer } from './doubles/peer.ts'
import { countedReads } from './doubles/ports.ts'
import { armedEligibility, armedStore, stallingAdoption } from './doubles/stalls.ts'
import { adoptStdio, storedRecord } from './doubles/world.ts'

const files = endpointRefOf('files')
const READ = actionNameOf('read')
const c1 = correlationKeyOf('c1')
const c2 = correlationKeyOf('c2')
const anonymousKey = {
  tenant: alice.tenant,
  account: { kind: 'anonymous' as const },
  holding: files.holding,
}
const ASKS: PeerReply = {
  kind: 'result',
  result: { resultType: 'input_required', requestState: 's1', inputRequests: { q: 1 } },
}

/**
 * A peer whose `read` first asks for input, then completes; adopted, with the catalog stored.
 * `shape` replaces ports with ones shaped on the peer's own.
 */
async function arranged(shape: (p: Peer) => Partial<McpPorts<Principal, string>> = () => ({})) {
  const p = peer({
    listing: { '': listing([{ name: 'read' }]) },
    calls: { read: [ASKS, completed([text('done')])] },
  })
  adoptStdio(p, files)
  const stored = await storedRecord(p, anonymousKey, ['read'])
  const digest = stored.actions[0]?.definitionDigest
  if (digest === undefined) throw new Error('no digest')
  const { services: s, table } = services({ ...p, ports: { ...p.ports, ...shape(p) } })
  return { p, digest, table, ...s }
}

type Arranged = Awaited<ReturnType<typeof arranged>>

/** The first call, which the peer answers with an input request; answers the generation. */
async function asked(c: Arranged, digest: DefinitionDigest): Promise<Generation> {
  const first = await c.invoker.invoke(alice, {
    ref: files,
    action: READ,
    args: jsonOf({}),
    expectedDefinition: digest,
    correlationKey: c1,
    signal: new AbortController().signal,
  })
  if (first.kind !== 'sent' || first.outcome.kind !== 'inputRequired') throw new Error('not asked')
  return first.outcome.issuedAt
}

function continuation(
  issuedAt: Generation,
  extra: Readonly<{ requestState?: RequestState; inputResponses?: unknown }> = {},
) {
  return {
    ref: files,
    action: READ,
    args: jsonOf({}),
    issuedAt,
    correlationKey: c2,
    signal: new AbortController().signal,
    ...(extra.requestState === undefined ? {} : { requestState: extra.requestState }),
    ...(extra.inputResponses === undefined ? {} : { inputResponses: jsonOf(extra.inputResponses) }),
  }
}

describe('continueWithInput (SPEC S2)', () => {
  it('completes on the same generation, sending the request state and the input responses', async () => {
    const c = await arranged()
    const issuedAt = await asked(c, c.digest)
    expect(
      await c.invoker.continueWithInput(
        alice,
        continuation(issuedAt, { requestState: requestStateOf('s1'), inputResponses: { q: 'a' } }),
      ),
    ).toMatchObject({ kind: 'sent', outcome: { kind: 'complete' } })
    const calls = c.p.requests('tools/call')
    expect(calls).toHaveLength(2)
    expect(calls[1]?.params).toMatchObject({
      name: 'read',
      arguments: {},
      requestState: 's1',
      inputResponses: { q: 'a' },
    })
  })

  it('is not sent once the connection changed generation: unknown, and no call on the new generation', async () => {
    const c = await arranged()
    const issuedAt = await asked(c, c.digest)
    expect(await c.connections.release(alice, files)).toMatchObject({ ok: { kind: 'released' } })
    expect(
      await c.invoker.continueWithInput(
        alice,
        continuation(issuedAt, { requestState: requestStateOf('s1'), inputResponses: { q: 'a' } }),
      ),
    ).toEqual({ kind: 'not-sent', reason: { kind: 'unknown' } })
    expect(c.p.requests('tools/call')).toHaveLength(1)
    expect(c.p.opens()).toBe(1)
    expect(await c.invoker.cancel(alice, c2)).toBe('unknown')
  })

  it('after closeAll is not sent: connection-unavailable, and nothing connects (S8)', async () => {
    const c = await arranged()
    const issuedAt = await asked(c, c.digest)
    await c.connections.closeAll()
    expect(
      await c.invoker.continueWithInput(
        alice,
        continuation(issuedAt, { requestState: requestStateOf('s1'), inputResponses: { q: 'a' } }),
      ),
    ).toEqual({ kind: 'not-sent', reason: { kind: 'connection-unavailable' } })
    expect(c.p.requests('tools/call')).toHaveLength(1)
    expect(c.p.opens()).toBe(1)
  })

  it('closeAll while the continuation waits on the gate: the same not sent, connection-unavailable, as a first call; the store is not read after it (S8)', async () => {
    let store: ReturnType<typeof countedReads> | undefined
    let armed: ReturnType<typeof armedEligibility> | undefined
    const c = await arranged(p => ({
      store: (store = countedReads(p.store)),
      eligibility: (armed = armedEligibility(p.eligibility)).port,
    }))
    if (store === undefined || armed === undefined) throw new Error('not shaped')
    const issuedAt = await asked(c, c.digest)
    const gate = armed.arm()
    const call = c.invoker.continueWithInput(
      alice,
      continuation(issuedAt, { requestState: requestStateOf('s1') }),
    )
    await gate.reached
    await c.connections.closeAll()
    const reads = store.reads()
    gate.release()
    expect(await call).toEqual({ kind: 'not-sent', reason: { kind: 'connection-unavailable' } })
    expect(store.reads()).toBe(reads)
    expect(c.p.requests('tools/call')).toHaveLength(1)
    expect(c.p.opens()).toBe(1)
  })

  it('closeAll while the continuation waits on the store: the same not sent, connection-unavailable, as a first call, not the unknown of step 6; nothing is built or sent after it (S8)', async () => {
    let store: ReturnType<typeof armedStore> | undefined
    const c = await arranged(p => ({ store: (store = armedStore(p.store)).port }))
    if (store === undefined) throw new Error('not shaped')
    const issuedAt = await asked(c, c.digest)
    const read = store.arm()
    const call = c.invoker.continueWithInput(
      alice,
      continuation(issuedAt, { requestState: requestStateOf('s1') }),
    )
    await read.reached
    await c.connections.closeAll()
    read.release()
    expect(await call).toEqual({ kind: 'not-sent', reason: { kind: 'connection-unavailable' } })
    expect(c.p.requests('tools/call')).toHaveLength(1)
    expect(c.p.opens()).toBe(1)
  })

  it('is not sent on a generation other than the one given, even while a connection is up', async () => {
    const c = await arranged()
    const issuedAt = await asked(c, c.digest)
    const other = generationOf(issuedAt + 1)
    expect(
      await c.invoker.continueWithInput(
        alice,
        continuation(other, { requestState: requestStateOf('s1') }),
      ),
    ).toEqual({ kind: 'not-sent', reason: { kind: 'unknown' } })
    expect(c.p.requests('tools/call')).toHaveLength(1)
  })

  it('with the input responses alone is lawful too: the continuation carries no request state', async () => {
    const c = await arranged()
    const issuedAt = await asked(c, c.digest)
    expect(
      await c.invoker.continueWithInput(
        alice,
        continuation(issuedAt, { inputResponses: { q: 'a' } }),
      ),
    ).toMatchObject({ kind: 'sent', outcome: { kind: 'complete' } })
    const second = c.p.requests('tools/call')[1]
    expect(second?.params).toMatchObject({ name: 'read', inputResponses: { q: 'a' } })
    expect(second?.params).not.toHaveProperty('requestState')
  })

  it('with the request state alone is lawful: the continuation carries no input responses', async () => {
    const c = await arranged()
    const issuedAt = await asked(c, c.digest)
    expect(
      await c.invoker.continueWithInput(
        alice,
        continuation(issuedAt, { requestState: requestStateOf('s1') }),
      ),
    ).toMatchObject({ kind: 'sent', outcome: { kind: 'complete' } })
    const second = c.p.requests('tools/call')[1]
    expect(second?.params).toMatchObject({ requestState: 's1' })
    expect(second?.params).not.toHaveProperty('inputResponses')
  })

  it('is not sent when the build answers a later generation than the one given: unknown, and no call on the new generation', async () => {
    const p = peer({
      listing: { '': listing([{ name: 'read' }]) },
      calls: { read: [ASKS, completed([text('done')])] },
    })
    adoptStdio(p, files)
    const stored = await storedRecord(p, anonymousKey, ['read'])
    const digest = stored.actions[0]?.definitionDigest
    if (digest === undefined) throw new Error('no digest')
    // Adoption reads: the first call's gate (1) and re-read (2); the continuation's gate (3) and
    // re-read (4). The fourth is delivered only when the case lets it go.
    const stalled = stallingAdoption(p.adoption, 4)
    const { services: s, table } = services({ ...p, ports: { ...p.ports, adoption: stalled.port } })
    const c = { p, digest, table, ...s }
    const issuedAt = await asked(c, digest)
    const [first] = table.currentOf(alice.tenant, files.holding)
    if (first === undefined) throw new Error('no connection')
    const continued = c.invoker.continueWithInput(
      alice,
      continuation(issuedAt, { requestState: requestStateOf('s1') }),
    )
    await settled()
    // The generation check before the build passed; now the connection is lost under the re-read.
    await loseOn(table, first, { reason: 'stream-broken', mark: 'connection-unavailable' })
    stalled.gate.resolve()
    expect(await continued).toEqual({ kind: 'not-sent', reason: { kind: 'unknown' } })
    expect(p.opens()).toBe(2)
    expect(p.requests('tools/call')).toHaveLength(1)
    expect(await c.invoker.cancel(alice, c2)).toBe('unknown')
  })

  it('with neither the request state nor the input responses rejects with TypeError before any place is taken', async () => {
    const c = await arranged()
    const issuedAt = await asked(c, c.digest)
    await expect(c.invoker.continueWithInput(alice, continuation(issuedAt))).rejects.toThrow(
      TypeError,
    )
    expect(c.p.requests('tools/call')).toHaveLength(1)
    expect(await c.invoker.cancel(alice, c2)).toBe('unknown')
  })

  it('rejects arguments that are not a JSON object with TypeError (R2)', async () => {
    const c = await arranged()
    const issuedAt = await asked(c, c.digest)
    await expect(
      c.invoker.continueWithInput(alice, { ...continuation(issuedAt), args: jsonOf([]) }),
    ).rejects.toThrow(TypeError)
    expect(c.p.requests('tools/call')).toHaveLength(1)
  })

  it('reads each field of the request once: input responses that are an accessor answer once, and that answer is what goes out (R2)', async () => {
    const c = await arranged()
    const issuedAt = await asked(c, c.digest)
    let reads = 0
    const unjudged: JsonValue = { kind: 'number', lexeme: 'NaN' }
    // The accessor answers nothing first and a tree that fails judgeJsonValue after.
    const request = Object.defineProperty(
      continuation(issuedAt, { requestState: requestStateOf('s1') }),
      'inputResponses',
      {
        enumerable: true,
        get(): JsonValue | undefined {
          reads += 1
          return reads === 1 ? undefined : unjudged
        },
      },
    )
    expect(await c.invoker.continueWithInput(alice, request)).toMatchObject({
      kind: 'sent',
      outcome: { kind: 'complete' },
    })
    expect(reads).toBe(1)
    const second = c.p.requests('tools/call')[1]
    expect(second?.params).toMatchObject({ requestState: 's1' })
    expect(second?.params).not.toHaveProperty('inputResponses')
  })

  it('rejects input responses whose value tree fails judgeJsonValue with TypeError before any place is taken (R2)', async () => {
    const c = await arranged()
    const issuedAt = await asked(c, c.digest)
    const inputResponses: JsonValue = {
      kind: 'array',
      items: [{ kind: 'number', lexeme: 'NaN' }],
    }
    await expect(
      c.invoker.continueWithInput(alice, { ...continuation(issuedAt), inputResponses }),
    ).rejects.toThrow(TypeError)
    expect(c.p.requests('tools/call')).toHaveLength(1)
    expect(await c.invoker.cancel(alice, c2)).toBe('unknown')
  })
})

tests/release.spec.ts.source:
// The connections port (SPEC S8, S9, group page "close()"): the close order, the report of the
// confirmed range only, the HTTP handle released with the close, and `closeAll` for the host.
import { describe, expect, it } from 'vitest'
import { core } from './doubles/core.ts'
import { endpointRefOf } from '@omne-harness/mcp-contract/testing'
import { alice, bob, mallory } from './doubles/identities.ts'
import { adoptHttp, adoptStdio, usualScript, world } from './doubles/world.ts'

const files = endpointRefOf('files')

describe('connections.release', () => {
  it('closes the transport before it stops the process, and reports the confirmed range', async () => {
    const { w, discovery, connections, status } = core(world({ script: usualScript() }))
    adoptStdio(w, files)
    await discovery.refresh(alice, { ref: files })
    expect(await connections.release(alice, files)).toEqual({
      ok: { kind: 'released', process: 'tree-confirmed' },
    })
    expect(w.trace).toEqual(['transport.close', 'process.stop'])
    expect(await status.inspect(alice, files)).toMatchObject({
      ok: { connection: { kind: 'none' } },
    })
    expect(await connections.release(alice, files)).toEqual({ ok: { kind: 'no-connection' } })
  })

  it.each(['root-only', 'unconfirmed'] as const)(
    'reports %s and keeps the state lost (close-unconfirmed) with the residual',
    async stop => {
      const { w, discovery, connections, status } = core(world({ script: usualScript(), stop }))
      adoptStdio(w, files)
      await discovery.refresh(alice, { ref: files })
      expect(await connections.release(alice, files)).toEqual({
        ok: { kind: 'released', process: stop },
      })
      expect(await status.inspect(alice, files)).toMatchObject({
        ok: {
          connection: {
            kind: 'lost',
            reason: 'close-unconfirmed',
            residual: [{ kind: 'process', confirmed: stop }],
          },
        },
      })
      // A second release asks the process to stop again and reports what it confirms now.
      expect(await connections.release(alice, files)).toEqual({
        ok: { kind: 'released', process: stop },
      })
      expect(w.landing.processes()).toEqual([{ stops: 2 }])
    },
  )

  it('rebuilds after an unconfirmed close with the next generation and no residual', async () => {
    const { w, discovery, connections, status } = core(
      world({ script: [...usualScript(), ...usualScript()], stop: 'root-only' }),
    )
    adoptStdio(w, files)
    await discovery.refresh(alice, { ref: files })
    await connections.release(alice, files)
    expect(await discovery.refresh(alice, { ref: files })).toEqual({
      ok: { kind: 'published', revision: 2 },
    })
    expect(await status.inspect(alice, files)).toMatchObject({
      ok: { connection: { kind: 'ready' } },
    })
    expect(await discovery.peer(alice, files)).toMatchObject({ ok: { generation: 2 } })
  })

  it('releases the HTTP credential handle exactly once, and reports no-process', async () => {
    const { w, discovery, connections } = core(world({ script: usualScript() }))
    adoptHttp(w, files)
    await discovery.refresh(alice, { ref: files })
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 0 }])
    expect(await connections.release(alice, files)).toEqual({
      ok: { kind: 'released', process: 'no-process' },
    })
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 1 }])
    expect(w.trace).toEqual(['transport.close', 'credential.release'])
  })

  it('releases the process credential handle once, after the process stopped', async () => {
    const { w, discovery, connections } = core(world({ script: usualScript() }))
    adoptStdio(w, files, { auth: 'static', env: [{ name: 'TOKEN', source: 'credential' }] })
    await discovery.refresh(alice, { ref: files })
    await connections.release(alice, files)
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 1 }])
    expect(w.trace).toEqual(['transport.close', 'process.stop', 'credential.release'])
  })

  it('answers no-connection when nothing was connected', async () => {
    const { w, connections } = core(world())
    adoptStdio(w, files)
    expect(await connections.release(alice, files)).toEqual({ ok: { kind: 'no-connection' } })
  })

  it('answers the gate refusal; a blocked endpoint is closed all the same', async () => {
    const { w, discovery, connections, status } = core(world({ script: usualScript() }))
    adoptStdio(w, files)
    await discovery.refresh(alice, { ref: files })
    w.eligibility.block(alice, files, 'disabled')
    expect(await connections.release(alice, files)).toEqual({
      failure: { kind: 'blocked', reason: 'disabled' },
    })
    expect(await status.inspect(alice, files)).toMatchObject({
      ok: { connection: { kind: 'none' } },
    })
    expect(await connections.release(bob, files)).toEqual({
      failure: { kind: 'not-available-to-you' },
    })
    expect(await connections.release(mallory, files)).toEqual({
      failure: { kind: 'not-available-to-you' },
    })
  })
})

describe('connections.closeAll', () => {
  it('closes every connection without asking adoption or eligibility', async () => {
    const { w, discovery, connections, status } = core(
      world({ script: [...usualScript(), ...usualScript()] }),
    )
    const shell = endpointRefOf('shell')
    adoptStdio(w, files)
    adoptHttp(w, shell)
    await discovery.refresh(alice, { ref: files })
    await discovery.refresh(alice, { ref: shell })
    const adoptionCalls = w.adoption.calls()
    const eligibilityCalls = w.eligibility.calls()
    expect(await connections.closeAll()).toEqual([
      { ref: files, process: 'tree-confirmed' },
      { ref: shell, process: 'no-process' },
    ])
    expect(w.adoption.calls()).toBe(adoptionCalls)
    expect(w.eligibility.calls()).toBe(eligibilityCalls)
    expect(await status.inspect(alice, files)).toMatchObject({
      ok: { connection: { kind: 'none' } },
    })
    expect(await status.inspect(alice, shell)).toMatchObject({
      ok: { connection: { kind: 'none' } },
    })
    expect(w.credentials.handles()).toEqual([{ acquired: 1, released: 1 }])
    expect(await connections.closeAll()).toEqual([])
  })

  it('reports only the confirmed range', async () => {
    const { w, discovery, connections } = core(
      world({ script: usualScript(), stop: 'unconfirmed' }),
    )
    adoptStdio(w, files)
    await discovery.refresh(alice, { ref: files })
    expect(await connections.closeAll()).toEqual([{ ref: files, process: 'unconfirmed' }])
    expect(await connections.closeAll()).toEqual([{ ref: files, process: 'unconfirmed' }])
  })
})

tests/status.spec.ts.source:
// The status port (SPEC S1, S7): the credential in four states and never its value, use in two
// states, the connection state with its residual, and the same answer to a principal without
// access whether the endpoint exists or not.
import assert from 'node:assert/strict'
import { describe, expect, it } from 'vitest'
import { core } from './doubles/core.ts'
import { endpointRefOf } from '@omne-harness/mcp-contract/testing'
import { alice, bob, mallory } from './doubles/identities.ts'
import { INVALID, adoptHttp, adoptStdio, usualScript, world } from './doubles/world.ts'

const files = endpointRefOf('files')
const nowhere = endpointRefOf('nowhere')

describe('status.inspect', () => {
  it.each([
    ['not-required', (w: ReturnType<typeof world>) => adoptStdio(w, files)],
    ['present', (w: ReturnType<typeof world>) => adoptHttp(w, files)],
    [
      'absent',
      (w: ReturnType<typeof world>) =>
        adoptHttp(w, files, { settings: { credential: { kind: 'absent' } } }),
    ],
    [
      'invalid',
      (w: ReturnType<typeof world>) => adoptHttp(w, files, { settings: { credential: INVALID } }),
    ],
  ] as const)(
    'reports the credential as %s and nothing else about it',
    async (credential, adopt) => {
      const { w, status } = core(world())
      adopt(w)
      const view = await status.inspect(alice, files)
      expect(view).toEqual({
        ok: { ref: files, connection: { kind: 'none' }, credential, use: { kind: 'usable' } },
      })
      expect(JSON.stringify(view)).not.toContain('hunter2')
      expect(JSON.stringify(view)).not.toContain('main')
    },
  )

  it('reports use as blocked with the reason for an eligible principal a setting blocks', async () => {
    const { w, status } = core(world())
    adoptStdio(w, files)
    w.eligibility.block(alice, files, 'local-command-not-enabled')
    expect(await status.inspect(alice, files)).toEqual({
      ok: {
        ref: files,
        connection: { kind: 'none' },
        credential: 'not-required',
        use: { kind: 'blocked', reason: 'local-command-not-enabled' },
      },
    })
  })

  it('reports the connection as ready after a refresh, and opens nothing itself', async () => {
    const { w, status, discovery } = core(world({ script: usualScript() }))
    adoptStdio(w, files)
    expect(await status.inspect(alice, files)).toMatchObject({
      ok: { connection: { kind: 'none' } },
    })
    await discovery.refresh(alice, { ref: files })
    expect(await status.inspect(alice, files)).toMatchObject({
      ok: { connection: { kind: 'ready' } },
    })
    expect(w.transports.calls.filter(call => call.kind === 'open')).toHaveLength(1)
  })

  it('reports lost with the residual a failed preparation left', async () => {
    const { w, status, discovery } = core(
      world({
        script: [{ discover: { kind: 'not-sent', cause: 'connection-unavailable' } }],
        stop: 'unconfirmed',
      }),
    )
    adoptStdio(w, files)
    await discovery.refresh(alice, { ref: files })
    expect(await status.inspect(alice, files)).toMatchObject({
      ok: {
        connection: {
          kind: 'lost',
          reason: 'preparation-failed',
          residual: [{ kind: 'process', confirmed: 'unconfirmed' }],
        },
      },
    })
  })

  it('answers not-available-to-you to a principal without eligibility', async () => {
    const { w, status } = core(world())
    adoptStdio(w, files)
    expect(await status.inspect(bob, files)).toEqual({ failure: { kind: 'not-available-to-you' } })
  })

  it('answers an outsider the same for an adopted and a missing endpoint', async () => {
    const { w, status } = core(world())
    adoptStdio(w, files)
    const forAdopted = await status.inspect(mallory, files)
    const forMissing = await status.inspect(mallory, nowhere)
    assert.deepStrictEqual(forAdopted, { failure: { kind: 'not-available-to-you' } })
    assert.deepStrictEqual(forMissing, forAdopted)
    const forBob = await status.inspect(bob, nowhere)
    assert.deepStrictEqual(forBob, forAdopted)
  })

  it('answers unknown when the adoption or the eligibility cannot be read', async () => {
    const { w, status } = core(world())
    adoptStdio(w, files)
    w.eligibility.setUnreadable(alice, files, true)
    expect(await status.inspect(alice, files)).toEqual({ failure: { kind: 'unknown' } })
    w.adoption.setUnreadable(true)
    expect(await status.inspect(alice, files)).toEqual({ failure: { kind: 'unknown' } })
  })

  it('closes the connection of an endpoint that is now blocked (invariant 6)', async () => {
    const { w, status, discovery } = core(world({ script: usualScript() }))
    adoptStdio(w, files)
    await discovery.refresh(alice, { ref: files })
    w.eligibility.block(alice, files, 'disabled')
    expect(await status.inspect(alice, files)).toMatchObject({
      ok: { connection: { kind: 'none' }, use: { kind: 'blocked', reason: 'disabled' } },
    })
    expect(await status.inspect(alice, files)).toMatchObject({
      ok: { connection: { kind: 'none' } },
    })
    expect(w.trace).toEqual(['transport.close', 'process.stop'])
  })
})

describe('status.list', () => {
  it('lists the usable and the blocked endpoints of the scope, not the ones without eligibility', async () => {
    const { w, status } = core(world())
    const shell = endpointRefOf('shell')
    const vault = endpointRefOf('vault')
    const elsewhere = endpointRefOf('elsewhere')
    adoptStdio(w, files)
    adoptStdio(w, shell)
    adoptHttp(w, vault)
    adoptStdio(w, elsewhere, { scope: 'other' })
    w.eligibility.block(alice, shell, 'local-command-not-enabled')
    w.eligibility.revoke(alice, vault)
    const listed = await status.list(alice, 'ws')
    expect(listed).toEqual({
      ok: [
        {
          ref: files,
          connection: { kind: 'none' },
          credential: 'not-required',
          use: { kind: 'usable' },
        },
        {
          ref: shell,
          connection: { kind: 'none' },
          credential: 'not-required',
          use: { kind: 'blocked', reason: 'local-command-not-enabled' },
        },
      ],
    })
    expect(await status.list(bob, 'ws')).toEqual({ ok: [] })
  })

  it('answers unknown for the whole list when any eligibility is unknown', async () => {
    const { w, status } = core(world())
    adoptStdio(w, files)
    adoptStdio(w, endpointRefOf('shell'))
    w.eligibility.setUnreadable(alice, endpointRefOf('shell'), true)
    expect(await status.list(alice, 'ws')).toEqual({ failure: 'unknown' })
  })

  it('answers unknown when the adoption cannot be read', async () => {
    const { w, status } = core(world())
    adoptStdio(w, files)
    w.adoption.setUnreadable(true)
    expect(await status.list(alice, 'ws')).toEqual({ failure: 'unknown' })
  })

  it('answers an empty list to an outsider, and opens nothing', async () => {
    const { w, status } = core(world({ script: usualScript() }))
    adoptStdio(w, files)
    expect(await status.list(mallory, 'ws')).toEqual({ ok: [] })
    expect(w.transports.calls).toHaveLength(0)
  })
})

